import{_ as s,o as t,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetSingularPass 设置奇异点跨越","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetSingularPass.md","filePath":"3. 指令/5. 设置指令/SetSingularPass.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/SetSingularPass.md"};function r(l,a,h,o,d,p){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="setsingularpass-设置奇异点跨越" tabindex="-1">SetSingularPass 设置奇异点跨越 <a class="header-anchor" href="#setsingularpass-设置奇异点跨越" aria-label="Permalink to &quot;SetSingularPass 设置奇异点跨越&quot;">​</a></h1><p>该指令用于<strong>开启或关闭机器人跨越腕部奇异点（Singular Point）的处理功能</strong>。奇异点是机器人运动学中的特殊位置，当机器人处于此类位置时，由于数学计算上的无穷解，往往会导致某些关节（特别是腕部关节）产生极高的旋转速度或导致运动轨迹偏离、系统报错。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetSingularPass(SingularPass) SetSingularPass(跨腕部奇异开关)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SingularPass：跨腕部奇异（SingularPass）</td><td>enum（枚举型：<code>OPEN</code> / <code>CLOSE</code>）</td><td>是否启用平滑跨越奇异点的算法。<br>* <strong>OPEN（开启）</strong>：当机器人轨迹接近奇异点（如第 4 轴与第 6 轴共线时），系统会自动调整姿态或速度分配，允许机器人平滑通过而不断流或报错。<br>* <strong>CLOSE（关闭）</strong>：不使用自动跨越逻辑。当路径经过奇异点附近时，可能会因为关节限速而导致轨迹畸变，或者直接报&quot;接近奇异点&quot;错误并停止运动。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>腕部奇异通常发生在机器人第 4 轴和第 6 轴完全对齐（共线）时。此时，为了维持 TCP 的直线运动，系统可能要求第 4 轴和第 6 轴以无限大的速度反向旋转。开启此功能后，算法会微调轨迹，以极小的姿态牺牲换取平稳通过。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSingularPass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OPEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>开启跨奇异点功能。如果从当前位置到 <strong>P1</strong> 的直线路径正好穿过奇异区域，机器人将尝试平滑度过而非停机报错。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>长距离直线运动</strong>：在大型工件表面涂胶、切割时，路径难以避开奇异点，开启此功能可确保生产连续性。</li><li><strong>离线编程执行</strong>：导入的复杂轨迹往往会意外触碰奇异点，开启 <code>OPEN</code> 能显著提高程序的调试通过率。</li><li><strong>注意</strong>：在对姿态精度要求极高（如高精度激光焊接）且轨迹可以手动优化的场景下，通常选择 <code>CLOSE</code> 以保持原始定义的姿态。</li></ul>`,18)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
